import React,{useRef,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {ReactFlow,ReactFlowProvider,Panel,Background,MiniMap,useReactFlow,useViewport,applyNodeChanges,SelectionMode} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import '../../../src/canvas-spike-scroll.css';
import {CanvasViewportControls} from '../../../src/features/canvas/CanvasViewportControls';
import {useCanvasReducedMotion} from '../../../src/features/canvas/useCanvasReducedMotion';
import {CANVAS_MIN_ZOOM,CANVAS_MAX_ZOOM} from '../../../src/core/canvas/viewportNavigation';
function Fixture(){const stage=useRef<HTMLDivElement>(null),active=useRef(false),flow=useReactFlow(),v=useViewport();const [saved,setSaved]=useState(0),[reduce,setReduce]=useState(false),[pan,setPan]=useState(false),[canvas,setCanvas]=useState(1);const reduced=useCanvasReducedMotion(reduce);const committed=useRef({x:0,y:0,zoom:1});const persist=(next:any)=>{if(JSON.stringify(committed.current)===JSON.stringify(next))return;committed.current=next;setSaved(n=>n+1);};const [nodes,setNodes]=useState([{id:'a',position:{x:220,y:150},data:{label:<div style={{height:170,display:'grid',placeItems:'center',background:'repeating-conic-gradient(#eee 0% 25%,#555 0% 50%) 0/32px 32px',color:'#090909'}}><b style={{background:'#eee',padding:8}}>细节参考 · 100%</b></div>},style:{width:240,background:'#252528',borderColor:'#555'}},{id:'b',position:{x:540,y:330},data:{label:<textarea className="nodrag" defaultValue={'输入框独立滚动\n'.repeat(20)} style={{width:180,height:110}}/>},style:{width:220}}]);
return <><header style={{height:40,display:'flex',gap:20,alignItems:'center',padding:'0 16px'}}><b>LuckyRay · 视图交互验收</b><label><input type="checkbox" checked={reduce} onChange={e=>setReduce(e.target.checked)}/>减少动画</label><label><input type="checkbox" checked={pan} onChange={e=>setPan(e.target.checked)}/>滚轮平移</label><button onClick={()=>setCanvas(c=>c+1)}>切换画布</button><output data-testid="camera">{JSON.stringify({...v,saved,canvas})}</output></header><div className="canvas-editor-root" style={{height:'calc(100vh - 40px)'}}><div className="canvas-editor-stage" ref={stage}><ReactFlow key={canvas} nodes={nodes} edges={[]} onNodesChange={changes=>setNodes(ns=>applyNodeChanges(changes,ns) as typeof ns)} minZoom={CANVAS_MIN_ZOOM} maxZoom={CANVAS_MAX_ZOOM} zoomOnScroll={false} panOnScroll={false} zoomOnPinch zoomOnDoubleClick={false} panOnDrag={[1]} selectionOnDrag selectionMode={SelectionMode.Partial} onMoveEnd={(_,next)=>{if(!active.current && JSON.stringify(flow.getViewport())===JSON.stringify(next))persist(next);}}><Background/><MiniMap pannable zoomable position="top-right"/><Panel position="bottom-left" className="canvas-controls"><CanvasViewportControls key={canvas} stage={stage} motionActive={active} reducedMotion={reduced} scrollToPan={pan} english={false} onSettled={persist}/></Panel></ReactFlow></div></div></>};
createRoot(document.getElementById('root')!).render(<React.StrictMode><ReactFlowProvider><Fixture/></ReactFlowProvider></React.StrictMode>);
